"""LaTeX tables of the article and of Online Resource 1, written from paper_numbers.py (generated files, rewritten on every run;
numbers are never edited by hand).
Output: output/table*.tex, output/esm_table*.tex
Usage: python -I paper_tables.py
"""
import os
import sys

sys.dont_write_bytecode = True
HERE = os.path.dirname(os.path.abspath(__file__))
if HERE not in sys.path:
    sys.path.insert(0, HERE)

import config  # noqa: E402
import numpy as np  # noqa: E402

import factor_graph as L  # noqa: E402
import paper_numbers as MN  # noqa: E402

OUT = config.OUTPUT
HEAD = "% Generated by paper_tables.py -- do not edit numbers by hand.\n"
NAME = dict(zero="ZS", newton="NP", ren="STA", pivot="PS", wang="WP", graph="FG")


def write(name, txt):
    os.makedirs(OUT, exist_ok=True)
    with open(os.path.join(OUT, name), "w", encoding="utf-8", newline="\n") as fh:
        fh.write(HEAD + txt)


def check_values(der):
    """The values in factor_graph must be the rounded sources (camera Monte Carlo, IMU budget, smoothness ratio, threshold)."""
    pairs = [(L.CAMERA["SX"], der["cam_SX"], 3), (L.CAMERA["SZ"], der["cam_SZ"], 3), (L.CAMERA["SH"], der["cam_SH"], 3),
             (L.CAMERA["D_STD"], der["cam_D"], 3), (L.CAMERA["SCOP"], der["cop_total_cam_mm"] / 1000, 3),
             (L.IMU["SX"], der["imu_SX"], 3), (L.IMU["SZ"], der["imu_SZ"], 3), (L.IMU["SH"], der["imu_SH"], 3),
             (L.IMU["D_STD"], der["imu_D_STD"], 3), (L.IMU["SCOP"], der["imu_cop_total_mm"] / 1000, 3),
             (L.MODEL["FX_RATIO"], der["ratio_median"], 2), (L.INSOLE["F_CONTACT"], der["thr_chosen"], 0)]
    for used, src, nd in pairs:
        if round(used, nd) != round(src, nd):
            raise SystemExit(f"factor_graph value {used} differs from its source {src}")


def ends():
    """Low and high value of every quantity of the sensitivity study, from run_sensitivity.settings() (the settings that ran)."""
    import run_sensitivity as RS
    import run_sensitivity_smoothness as RSM  # sigma_sm halved and doubled (its own run; importing it patches nothing)
    out = {}
    for row, end, mch, dch in RS.settings() + RSM.settings():
        if row == "main":
            continue
        for k, v in mch.items():
            out[(k, end)] = v
        for k, v in dch.items():
            for case, dev in (("camera", L.CAMERA), ("imu", L.IMU)):
                out[(case, k, end)] = v[1] if isinstance(v, tuple) else dev[k] * v
    if (out[("camera", "SM_SCALE", "low")], out[("camera", "SM_SCALE", "high")]) != (0.5, 2.0):
        raise SystemExit("SM_SCALE bounds are not half and double")
    for k in ("SI", "G_STD", "F_CONTACT"):
        for end in ("low", "high"):
            if out[("camera", k, end)] != out[("imu", k, end)]:
                raise SystemExit(f"{k}: bounds differ between the kinematic cases")
    return out


def g(x, scale=1.0):
    return f"{round(scale * x, 6):g}"


def dec(x, nmin):
    """At least nmin decimals, more only where the value needs them (0.0185, 0.074, 1.10)."""
    s = f"{x:.{nmin + 3}f}"
    while len(s.split(".")[1]) > nmin and s.endswith("0"):
        s = s[:-1]
    return s


def sgn(v):
    """Signed change with one decimal; a change that rounds to zero is printed 0.0, without a sign."""
    s = f"{v:+.1f}"
    return "0.0" if s in ("+0.0", "-0.0") else s


