def table_kinematic():
    e = ends()
    spec = (("Horizontal balance", r"$\sigma_{\mathrm{hor}}$", "SX", r"\BW"), ("Vertical balance", r"$\sigma_{\mathrm{ver}}$", "SZ", r"\BW"),
            ("Moment balance", r"$\sigma_{\mathrm{mom}}$", "SH", r"m\,BW"), ("Offset prior", r"$\sigma_{b}$", "D_STD", r"m\,BW"),
            ("CoP", r"$\sigma_{\mathrm{CoP}}$", "SCOP", "mm"))
    rows = []
    for name, sym, k, unit in spec:
        cells = []
        for case, dev in (("camera", L.CAMERA), ("imu", L.IMU)):
            if unit == "mm":
                cells += [f"{1000 * dev[k]:.0f}", g(e[(case, k, "low")], 1000), g(e[(case, k, "high")], 1000)]
            elif unit == r"\BW":
                cells += [f"{100 * dev[k]:.1f}", dec(100 * e[(case, k, "low")], 1), dec(100 * e[(case, k, "high")], 1)]
            else:
                cells += [f"{dev[k]:.3f}", dec(e[(case, k, "low")], 3), dec(e[(case, k, "high")], 3)]
        rows.append(f"{name} ({unit}) & {sym} & " + " & ".join(cells) + r" \\")
    txt = r"""\begin{table}
\caption{Uncertainties that depend on the kinematics, computed from the data, and the bounds of the sensitivity study
(Sect.~\ref{sec:res:sensitivity}). The balance and offset uncertainties are varied together}
\label{tab:kinematic}
\footnotesize
\renewcommand{\arraystretch}{1.15}
\setlength{\tabcolsep}{3.5pt}
\begin{tabular}{@{}ll*{6}{c}@{}}
\toprule
\multirow{3}{*}{Quantity} & \multirow{3}{*}{Symbol} & \multicolumn{3}{c}{Camera kinematics} & \multicolumn{3}{c}{IMU kinematics} \\
\cmidrule(lr){3-5}\cmidrule(l){6-8}
 & & \multirow{2}{*}{Value} & \multicolumn{2}{c}{Sensitivity} & \multirow{2}{*}{Value} & \multicolumn{2}{c}{Sensitivity} \\
\cmidrule(lr){4-5}\cmidrule(l){7-8}
 & & & Low & High & & Low & High \\
\midrule
""" + "\n".join(rows) + r"""
\bottomrule
\end{tabular}

\smallskip
{\footnotesize The CoP uncertainty also includes the sensor's error of 15\,mm~\cite{morin2022}.\par}
\end{table}
"""
    write("table2_kinematic.tex", txt)


def table_results(main):
    tab = main["table"]
    cols = MN.COLS + ("fz_stance",)
    fmt = dict(stance="{:.2f}", ds="{:.2f}", ss="{:.2f}", fz_stance="{:.2f}", ankle="{:.3f}", knee="{:.3f}", hip="{:.3f}")
    lines = []
    for case, title in (("camera", "Camera kinematics"), ("imu", "IMU kinematics")):
        meths = [m for m in MN.METHODS if m != "wang" or case == "imu"]
        best = {}
        for k in cols:
            vals = {m: tab[(case, m, k)] for m in meths if np.isfinite(tab[(case, m, k)])}
            best[k] = min(vals, key=vals.get)  # lowest of the block in every column (caption rule)
        lines.append(rf"\multicolumn{{8}}{{@{{}}l}}{{\emph{{{title}}}}}\\")
        for m in meths:
            cells = []
            for k in cols:
                v = tab[(case, m, k)]
                if not np.isfinite(v):
                    cells.append("--")
                    continue
                s = fmt[k].format(v)
                cells.append(rf"\textbf{{{s}}}" if best[k] == m else s)
            if m == "graph":
                lines.append(r"\addlinespace[1pt]")
            lines.append(f"{NAME[m]} & " + " & ".join(cells) + r" \\")
        if case == "camera":
            lines.append(r"\addlinespace")
    txt = r"""\begin{table}
\caption{RMSE against the reference solution. Lowest error of each block in bold}
\label{tab:results}
\footnotesize
\renewcommand{\arraystretch}{1.12}
\setlength{\tabcolsep}{2.4pt}
\begin{tabular}{@{}l*{7}{c}@{}}
\toprule
 & \multicolumn{3}{c}{Shear (\BW)} & \multicolumn{3}{c}{Joint moment (\Nmkg)} & Vertical force (\BW) \\
\cmidrule(lr){2-4}\cmidrule(lr){5-7}\cmidrule(l){8-8}
Method & St & DS & SS & Ankle & Knee & Hip & St \\
\midrule
""" + "\n".join(lines) + r"""
\bottomrule
\end{tabular}

\smallskip
{\footnotesize ZS, NP and STA use the insole's vertical force as measured; PS estimates its own, and WP releases joint moments
only.\par}
\end{table}
"""
    write("table3_results.tex", txt)


def table_ablation(abl):
    label = {"no direction": "Direction", "no force smoothness": "Smoothness", "no moment balance": "Moment balance",
             "no scale and offset": "Scales and offset", "balances and sensors only": "All four"}
    lines = []
    order = ("no moment balance", "no direction", "no force smoothness", "no scale and offset",
             "balances and sensors only")
    assert sorted(order) == sorted(MN.ABL)
    for arm in order:
        cells = []
        for case in MN.CASES:
            a = abl[(case, arm)]
            cells += [f"${sgn(a['shear'])}$ ({a['n_shear']})", f"${sgn(a['moments'])}$ ({a['n_moments']})"]
        if arm == "balances and sensors only":
            lines.append(r"\addlinespace[1pt]")
        lines.append(f"{label[arm]} & " + " & ".join(cells) + r" \\")
    txt = r"""\begin{table}
\caption{Ablation: change in error (\%; plus, the error grows, so the removed item helps) when one factor, or the scales and the
offset, is removed from the factor graph; in parentheses, the number of the nine subjects whose error grows. Shear: stance
RMSE; moments: mean change of the three joint-moment errors. All four: only the horizontal and vertical balances and the two
sensor factors remain}
\label{tab:ablation}
\footnotesize
\renewcommand{\arraystretch}{1.12}
\setlength{\tabcolsep}{4pt}
\begin{tabular}{@{}l*{4}{c}@{}}
\toprule
 & \multicolumn{2}{c}{Camera kinematics} & \multicolumn{2}{c}{IMU kinematics} \\
\cmidrule(lr){2-3}\cmidrule(l){4-5}
Removed & Shear & Moments & Shear & Moments \\
\midrule
""" + "\n".join(lines) + r"""
\bottomrule
\end{tabular}
\end{table}
"""
    write("table4_ablation.tex", txt)


def table_sensitivity(sens):
    label = {"pivot height": "Pivot height $d_z$", "pivot forward": "Pivot ahead $d_x$", "direction deviation": r"Direction $\sigma_{\mathrm{dir}}$",
             "smoothness ratio": r"Smoothness ratio $\rho$",
             "kinematic uncertainties": (r"Balance and offset",
                                         r"\quad $\sigma_{\mathrm{hor}}$, $\sigma_{\mathrm{ver}}$, $\sigma_{\mathrm{mom}}$, $\sigma_{b}$"),
             "insole Fz and scale": r"Insole $\sigma_{\mathrm{F}}$, $\sigma_{\gamma}$", "CoP": r"CoP $\sigma_{\mathrm{CoP}}$",
             "contact threshold": r"Contact threshold $F_{\mathrm{th}}$", "smoothness": r"Smoothness $\sigma_{\mathrm{sm}}$"}
    short = dict(stance="St", ds="DS", ss="SS", ankle="A", knee="K", hip="H")
    joint_name = dict(ankle="ankle", knee="knee", hip="hip")
    used = {k for s in sens.values() for k in s["lost"]}
    joint_note = "; ".join(f"{short[k]}, {joint_name[k]}" for k in ("ankle", "knee", "hip") if k in used)
    lines = []
    order = ("pivot height", "pivot forward", "direction deviation", "smoothness ratio", "contact threshold",
             "insole Fz and scale", "smoothness", "kinematic uncertainties", "CoP")
    assert sorted(order) == sorted(MN.SENS)
    for row in order:
        for end in ("low", "high"):
            cells = []
            for case in MN.CASES:
                s = sens[(case, row, end)]
                lost = ", ".join(short[k] for k in s["lost"]) if s["lost"] else "--"
                cells += [f"${sgn(s['shear'])}$", f"${sgn(s['moments'])}$", lost]
            lab = label[row] if isinstance(label[row], tuple) else (label[row], "")
            name = lab[0] if end == "low" else lab[1]
            lines.append(f"{name} & {end} & " + " & ".join(cells) + r" \\")
    txt = r"""\begin{table}
\caption{Sensitivity of the factor graph to its values. One value, or group, is moved to its low or high bound in
Tables~\ref{tab:common} and~\ref{tab:kinematic}, the others held. Shear and Moments: change in error as in
Table~\ref{tab:ablation}. Not lowest: the shear and joint-moment columns of Table~\ref{tab:results} in which the factor graph no longer has the
lowest error of all methods; --, lowest in all}
\label{tab:sensitivity}
\footnotesize
\renewcommand{\arraystretch}{1.08}
\setlength{\tabcolsep}{2.6pt}
\begin{tabular}{@{}ll*{6}{c}@{}}
\toprule
 & & \multicolumn{3}{c}{Camera kinematics} & \multicolumn{3}{c}{IMU kinematics} \\
\cmidrule(lr){3-5}\cmidrule(l){6-8}
Value & End & Shear & Moments & Not lowest & Shear & Moments & Not lowest \\
\midrule
""" + "\n".join(lines) + r"""
\bottomrule
\end{tabular}

\smallskip
{\footnotesize JOINTNOTE. With IMU kinematics the factor graph already lacks the lowest ankle error in the main setting (WP is
lower; Table~\ref{tab:results}), so the ankle is not counted there. At the contact-threshold ends ZS, NP, STA and PS are
recomputed with the same threshold.\par}
\end{table}
""".replace("JOINTNOTE", joint_note)
    write("table5_sensitivity.tex", txt)


