def esm_impl(der):
    """Table S1: implementation details, every number read from the code that ran."""
    import camera_mc as K
    import pivot_split as CP
    import imu_budget as W
    import inspect
    import planar_model as sp_
    import wang_segments as wr
    hat = sp_.SEG["hat"]
    src_b = inspect.getsource(wr.build)
    src_c = inspect.getsource(wr.insole_cop_to_lab)
    sig_a = inspect.signature(W.align_insole).parameters
    sig_p = inspect.signature(CP.castellaz).parameters
    sig_t = inspect.signature(CP.total_force).parameters
    for frag, src in (("L_hat = 0.288 * height", src_b), ("heel = ank - 0.25 * (L / 0.75) * u", src_c)):
        if frag not in src:
            raise SystemExit("code changed: " + frag)
    if not (sig_p["how"].default == "2025" and sig_p["cop_z"].default == 0.0):
        raise SystemExit("PS defaults changed")
    span, coarse, fine = (sig_a[k].default for k in ("span", "coarse", "fine"))
    rows = [
        (r"Head--arms--trunk (HAT)", rf"Rigid, non-rotating block above the midpoint of the hip joints; length "
         rf"0.288 body heights; mass {hat['m']:.3f} of body mass, CoM {hat['c']:.3f} and radius of gyration {hat['rg']:.3f} "
         rf"of its length~\cite{{winter2009}}"),
        (r"Insole CoP on the foot", r"The insole gives the CoP as a distance from the heel along the foot; it is placed on "
         r"the line from the heel point toward the toe point. Camera: heel marker and fifth-metatarsal marker. IMU: the "
         r"suit's toe point, and a heel point behind the ankle by one third of the ankle--toe distance (the ankle at a "
         r"quarter of the foot length)"),
        (r"IMU time alignment", rf"Shifts within $\pm{span:g}$\,s, on a grid of {1000 * coarse:g}\,ms, then "
         rf"{1000 * fine:g}\,ms around the best; score: correlation of the suit's vertical CoM acceleration with the "
         rf"summed insole force (set to zero below {W.THR:g}\,N), first and last second left out; allowed only where the "
         rf"left--right foot-height difference correlates positively with the right--left force difference. Own shift "
         rf"where the score is {W.R_MIN:g} or more ({der['imu_reliable']} trials), else the median of those"),
        (r"PS", rf"Whole-body force smoothed by a centered moving mean, {1000 * sig_t['ap_s'].default:g}\,ms horizontal and "
         rf"{1000 * sig_t['v_s'].default:g}\,ms vertical~\cite{{castellaz2025}}; pivot {CP.VPP_BH:g} body heights above the "
         rf"pelvis point~\cite{{castellaz2024}}; each foot's direction from its CoP at ground level; double support by "
         rf"non-negative least squares on the two directions, single support all to the loaded foot; Savitzky--Golay "
         rf"filter, order 1, {sig_p['sg'].default} frames, after the split"),
    ]
    body = "\n".join(rf"{a} & {b} \\" + ("\n\\addlinespace" if i < len(rows) - 1 else "") for i, (a, b) in enumerate(rows))
    txt = r"""\begin{table}[!htbp]
\caption{Implementation details}
\label{tab:s:impl}
\footnotesize
\renewcommand{\arraystretch}{1.15}
\begin{tabular}{@{}p{0.24\textwidth}p{0.72\textwidth}@{}}
\toprule
Item & Rule \\
\midrule
""" + body + r"""
\bottomrule
\end{tabular}
\end{table}
"""
    write("esm_table1_impl.tex", txt)


