def esm_contrasts(main):
    """Table S3: FG against the closest competitor of Table 3 in every column, and the CoP against the insole's."""
    C = main["contrast"]
    unit = dict(stance=r"\BW", ds=r"\BW", ss=r"\BW", ankle=r"\Nmkg", knee=r"\Nmkg", hip=r"\Nmkg", cop="mm")
    name = dict(stance="Shear, St", ds="Shear, DS", ss="Shear, SS", ankle="Ankle moment", knee="Knee moment",
                hip="Hip moment", cop="CoP")
    nd = dict(stance=2, ds=2, ss=2, ankle=3, knee=3, hip=3, cop=1)
    lines = []
    for case, title in (("camera", "Camera kinematics"), ("imu", "IMU kinematics")):
        lines.append(rf"\multicolumn{{7}}{{@{{}}l}}{{\emph{{{title}}}}}\\")
        for k in MN.COLS + ("cop",):
            c = C[(case, k)]
            fgv = main["table"][(case, "graph", k)] if k != "cop" else main[(case, "cop_graph")]
            comp = "insole" if k == "cop" else NAME[c["best"]]
            q = nd[k]
            lines.append(f"{name[k]} ({unit[k]}) & {comp} & {fgv:.{q}f} & {c['best_val']:.{q}f} & ${c['pct']:+.0f}$ & "
                         f"${c['lo']:.{q}f}$ to ${c['hi']:.{q}f}$ & {c['n_better']} of {c['n']} " + r"\\")
        if case == "camera":
            lines.append(r"\addlinespace")
    txt = r"""\begin{table}[!htbp]
\caption{The factor graph against the closest competing method of Table~3 in each shear and joint-moment column (for the CoP, against the
insole's CoP as placed): subject means, difference in percent of the competitor's mean, paired 95\,\% $t$ interval of the
difference over the nine subjects, and the subjects with the lower error with the factor graph}
\label{tab:s:contrasts}
\footnotesize
\renewcommand{\arraystretch}{1.12}
\setlength{\tabcolsep}{3.5pt}
\begin{tabular}{@{}llccccc@{}}
\toprule
Column & Closest & FG & Closest & \% & 95\,\% interval & FG lower \\
\midrule
""" + "\n".join(lines) + r"""
\bottomrule
\end{tabular}
\end{table}
"""
    write("esm_table3_contrasts.tex", txt)


def esm_speed(sp):
    """Table S4: the comparison of Table S3 by speed."""
    speeds = sorted({v for (_, v, _) in sp})
    pct0 = lambda x: "0" if round(x) == 0 else f"{round(x):+d}"  # noqa: E731
    lines = []
    for case, title in (("camera", "Camera kinematics"), ("imu", "IMU kinematics")):
        lines.append(rf"\multicolumn{{7}}{{@{{}}l}}{{\emph{{{title}}}}}\\")
        for v in speeds:
            cells = [f"${pct0(sp[(case, v, k)]['pct'])}$ ({sp[(case, v, k)]['n_better']}/{sp[(case, v, k)]['n']})"
                     for k in MN.COLS]
            lines.append(f"{v:.2f} & " + " & ".join(cells) + r" \\")
        if case == "camera":
            lines.append(r"\addlinespace")
    txt = r"""\begin{table}[!htbp]
\caption{The factor graph against the closest competing method by walking speed: difference of the subject means in
percent of the competitor's mean (minus, the factor graph is lower) and, in parentheses, the subjects with the lower error
with the factor graph. The competitor is PS in every column except the ankle with IMU kinematics, where it is WP}
\label{tab:s:speed}
\footnotesize
\renewcommand{\arraystretch}{1.12}
\setlength{\tabcolsep}{3.2pt}
\begin{tabular}{@{}l*{6}{c}@{}}
\toprule
 & \multicolumn{3}{c}{Shear} & \multicolumn{3}{c}{Joint moment} \\
\cmidrule(lr){2-4}\cmidrule(l){5-7}
Speed (m/s) & St & DS & SS & Ankle & Knee & Hip \\
\midrule
""" + "\n".join(lines) + r"""
\bottomrule
\end{tabular}
\end{table}
"""
    write("esm_table4_speed.tex", txt)


def esm_direction(dn):
    """Table S5: the factor graph with and without the direction factor, by window."""
    rows = [(r"Shear (\BW)", None, None)]
    rows += [(rf"\quad {w}", f"shear_{k}", 2) for w, k in (("St", "stance"), ("DS", "ds"), ("SS", "ss"))]
    rows += [(r"Vertical force (\BW)", None, None)]
    rows += [(rf"\quad {w}", f"fz_{k}", 2) for w, k in (("St", "stance"), ("DS", "ds"), ("SS", "ss"))]
    rows += [(r"CoP, St (mm)", "cop_stance_mm", 1)]
    for j in MN.JOINTS:
        rows += [(rf"{j.capitalize()} moment (\Nmkg)", None, None)]
        rows += [(rf"\quad {w}", f"{j}_{k}", 3) for w, k in (("All", "all"), ("DS", "ds"), ("SS", "ss"))]
    lines = []
    for lab, k, q in rows:
        if k is None:
            lines.append(rf"\multicolumn{{5}}{{@{{}}l}}{{{lab}}}\\")
            continue
        cells = [f"{dn[(case, arm)][k]:.{q}f}" for case in MN.CASES for arm in ("main", "no direction")]
        lines.append(f"{lab} & " + " & ".join(cells) + r" \\")
    lines.append(r"\addlinespace")
    lines.append(r"Offset $b$ (m\,BW) & " + " & ".join(f"${dn[(case, arm, 'b')]:.3f}$" for case in MN.CASES
                                                       for arm in ("main", "no direction")) + r" \\")
    txt = r"""\begin{table}[!htbp]
\caption{The factor graph with and without the direction factor, by window: subject means of the RMSE against the
reference solution (windows of Sect.~5.2; All, every scored frame) and the median offset over trials}
\label{tab:s:direction}
\footnotesize
\renewcommand{\arraystretch}{1.1}
\setlength{\tabcolsep}{4pt}
\begin{tabular}{@{}l*{4}{c}@{}}
\toprule
 & \multicolumn{2}{c}{Camera kinematics} & \multicolumn{2}{c}{IMU kinematics} \\
\cmidrule(lr){2-3}\cmidrule(l){4-5}
 & With & Without & With & Without \\
\midrule
""" + "\n".join(lines) + r"""
\bottomrule
\end{tabular}
\end{table}
"""
    write("esm_table5_direction.tex", txt)


def all_tables(N):
    check_values(N["der"])
    table_common(N["der"])
    table_kinematic()
    table_results(N["main"])
    table_ablation(N["abl"])
    table_sensitivity(N["sens"])
    esm_impl(N["der"])
    esm_mc(N["der"])
    esm_contrasts(N["main"])
    esm_speed(N["speed"])
    esm_direction(N["dirn"])


if __name__ == "__main__":
    all_tables(MN.all_numbers())
    print("tables written to", OUT)
